"""Plan a workflow around inputs the user already generated by hand.

`mace submit --progress` is the opt-in counterpart to the rule that a manual
submission never progresses on its own: progression needs a plan, so this
module writes a real one before the decks go to SLURM.

By the time anyone runs `mace submit`, the .d12/.d3 files exist — they came
from `mace opt2d12`/`mace opt2d3`/`mace convert`. So there is no CIF
conversion step and no first-step generation here: the existing decks ARE the
starting point (`{"source": "existing_d12"}`), and the plan describes what
should follow them.

Two levels, matching what the flag was given:

``--progress TEMPLATE``
    Sequence from the named template, per-step settings from the same
    non-interactive defaults `mace workflow --quick-start` uses. Fast, and the
    follow-up steps at least come from a real plan rather than whatever the
    engine would have improvised.

``--progress interactive``
    The planner's own step-configuration prompts — the same ones
    `mace workflow --interactive` asks — so SP functionals, BAND paths, DOSS
    windows and SLURM resources are yours, not defaults.
"""
import re
from datetime import datetime
from pathlib import Path
from types import SimpleNamespace
from typing import Any, Callable, Dict, List, Optional, Tuple

from mace.workflow.common.constants import WORKFLOW_TEMPLATES
from mace.utils import ui


def available_templates() -> List[str]:
    """Template names accepted by ``--progress`` (plus ``interactive``)."""
    return sorted(WORKFLOW_TEMPLATES)


# Same values `configure_queue_management` offers as its defaults, used when
# --progress names a template (that mode asks no questions).
DEFAULT_QUEUE_CONFIG = {
    "max_jobs": 950,
    "reserve_slots": 50,
    "max_submit_batch": 10,
    "max_recovery_attempts": 3,
}


def _mint_workflow_id(base_dir=None) -> str:
    from mace.workflow.context import new_workflow_id
    return new_workflow_id(base_dir)


def _template_plan(planner, sequence: List[str], input_dir: Path,
                   input_files: List[Path], workflow_id: str,
                   max_jobs: int, walltime: Optional[str] = None,
                   customize: Optional[Callable[[Dict[str, Any], str], None]] = None,
                   ) -> Dict[str, Any]:
    """Quick-start's plan builder, fed existing decks instead of CIFs.

    ``customize(plan, workflow_id)`` (a workflow spec's step settings and
    resources, mace/workflow/spec.py) changes the plan after the walltime and
    before the job scripts are written; without it the plan is the
    template's."""
    from mace.run_mace import create_quick_workflow_plan

    args = SimpleNamespace(max_jobs=max_jobs, work_dir=str(planner.work_dir))
    plan = create_quick_workflow_plan(input_dir, input_files, "d12", sequence, args)

    # Must precede copy_and_customize_scripts — that is what bakes the resource
    # directives into workflow_scripts/*.sh.
    if walltime:
        _apply_walltime(plan["step_configurations"], walltime)
    if customize is not None:
        customize(plan, workflow_id)

    # Creating the planner turned this directory into a workflow root, so the
    # queue manager now resolves SLURM templates out of workflow_scripts/
    # instead of the plain submitcrystal23.sh generator. Materialize them, or
    # the very first submission dies with "Submit script not found".
    # never more than this user's SLURM MaxSubmitJobs allows (site.clamp_queue)
    from mace.workflow.planner import clamp_queue_config, queue_defaults
    queue_config = dict(DEFAULT_QUEUE_CONFIG)
    queue_config["max_jobs"], queue_config["reserve_slots"] = queue_defaults(
        queue_config["max_jobs"], queue_config["reserve_slots"])
    queue_config["max_jobs"], queue_config["reserve_slots"] = clamp_queue_config(
        queue_config["max_jobs"], queue_config["reserve_slots"])
    planner.copy_and_customize_scripts(plan["step_configurations"], workflow_id,
                                       queue_config)
    plan["queue_management"] = queue_config
    plan["scripts_directory"] = str(planner.work_dir / "workflow_scripts")
    return plan


def _interactive_plan(planner, sequence: List[str], input_dir: Path,
                      input_files: List[Path], workflow_id: str,
                      max_jobs: int, walltime: Optional[str] = None) -> Dict[str, Any]:
    """The planner's real prompts, minus the CIF/first-step questions."""
    # has_cifs=False makes step 1 "use the existing D12 files as-is", which is
    # exactly true here — the user built them. The decks size the job offers
    # when the site turned size-aware suggestions on ([resources] auto).
    planner.auto_inputs = list(input_files)
    step_configs = planner.configure_workflow_steps(sequence, False)
    queue_config = planner.configure_queue_management()
    # An explicit --walltime wins over whatever the prompts collected, and must
    # be applied before the scripts are written.
    if walltime:
        _apply_walltime(step_configs, walltime)
    planner.copy_and_customize_scripts(step_configs, workflow_id, queue_config)

    return {
        "created": datetime.now().isoformat(),
        "mode": "manual_progress",
        "input_type": "d12",
        "input_directory": str(input_dir),
        "input_files": {"d12": [str(f) for f in input_files], "cif": []},
        "workflow_sequence": sequence,
        "step_configurations": step_configs,
        "cif_conversion_config": None,
        "queue_management": queue_config,
        "scripts_directory": str(planner.work_dir / "workflow_scripts"),
        "execution_settings": {
            "max_concurrent_jobs": max_jobs,
            "enable_material_tracking": True,
            "auto_progression": True,
            # a cap somebody chose (--max-jobs, a spec's execution.max_jobs) is kept even when it is 200
            **({"max_jobs_explicit": True} if max_jobs is not None else {}),
        },
    }


def _apply_walltime(step_configs: Dict[str, Any], walltime: str) -> None:
    """Force every step's SLURM walltime, in place.

    The per-type defaults are production-sized (7 days for OPT, 3 for SP). For a
    test run those sit in the queue far longer than the job needs, so allow one
    override to cover every step of the plan.
    """
    for cfg in step_configs.values():
        slurm = cfg.get("slurm_config")
        if not isinstance(slurm, dict):
            continue
        if isinstance(slurm.get("resources"), dict):
            slurm["resources"]["walltime"] = walltime
        for script in (slurm.get("scripts") or {}).values():
            if isinstance(script, dict) and isinstance(script.get("resources"), dict):
                script["resources"]["walltime"] = walltime


def build_progress_plan(work_dir: Path, db_path: str, input_files: List[Path],
                        progress: str, max_jobs: Optional[int] = None,
                        walltime: Optional[str] = None,
                        job_arrays: Optional[Dict[str, Any]] = None,
                        sequence: Optional[List[str]] = None,
                        customize: Optional[Callable[[Dict[str, Any], str], None]] = None,
                        ) -> Tuple[Path, str, List[str]]:
    """Write a workflow plan covering ``input_files`` and what follows them.

    Args:
        work_dir: where ``workflow_configs/`` is written (and where the
            completion callback will look for the plan).
        db_path: materials database the submissions will be recorded in.
        input_files: the decks about to be submitted.
        progress: a template name, or ``"interactive"``.
        max_jobs: concurrent-job ceiling recorded in the plan.
        job_arrays: the plan's job_arrays setting (`mace submit --array`), the
            same key `mace workflow --array` writes.
        sequence: a custom step sequence instead of the template's (a
            workflow spec); ``progress`` is then only its name.
        customize: see ``_template_plan`` (template mode only).

    Returns:
        ``(plan_file, workflow_id, sequence)``.

    Raises:
        ValueError: unknown template name.
    """
    from mace.workflow.planner import WorkflowPlanner

    work_dir = Path(work_dir).resolve()
    interactive = progress.strip().lower() == "interactive"
    if not interactive and sequence is None and progress not in WORKFLOW_TEMPLATES:
        raise ValueError(
            f"Unknown workflow template '{progress}'. "
            f"Choose one of: {', '.join(available_templates())}, or 'interactive'.")

    # Constructing the planner creates workflow_configs/outputs/temp/scripts.
    # That is intended here (this run IS becoming a workflow) and is why it
    # never happens on the default `mace submit` path.
    planner = WorkflowPlanner(str(work_dir), db_path)
    workflow_id = _mint_workflow_id(planner.work_dir)
    input_dir = Path(input_files[0]).resolve().parent if input_files else work_dir

    if interactive:
        sequence = planner.plan_workflow_sequence()
        plan = _interactive_plan(planner, sequence, input_dir, input_files,
                                 workflow_id, max_jobs, walltime)
    else:
        sequence = list(sequence if sequence is not None else WORKFLOW_TEMPLATES[progress])
        plan = _template_plan(planner, sequence, input_dir, input_files,
                              workflow_id, max_jobs, walltime, customize=customize)

    # Mint the id HERE and write it into the plan. Quick-start plans carry no
    # workflow_id and let the executor mint one; there is no executor in this
    # path — the submissions themselves must be stamped with the same id the
    # plan is filed under, or the completion callback cannot find the plan.
    plan["workflow_id"] = workflow_id
    # The job scripts run this workflow in its own context
    # (.mace_context_<id>), which keeps its own copy of the templates its
    # later steps are built from.
    from mace.workflow.context import keep_workflow_scripts
    keep_workflow_scripts(work_dir, workflow_id, [
        script.get("step_specific_name")
        for step in (plan.get("step_configurations") or {}).values()
        for script in (((step or {}).get("slurm_config") or {}).get("scripts") or {}).values()
        if isinstance(script, dict) and script.get("step_specific_name")])
    if job_arrays:
        plan["job_arrays"] = job_arrays
    plan_file = planner.save_workflow_plan(plan)
    return plan_file, workflow_id, sequence


def position_in_sequence(calc_type: str, sequence: List[str]) -> Optional[int]:
    """1-based step number of ``calc_type`` in ``sequence``, else None.

    A hand-made deck can start anywhere in the plan (submitting an SP after a
    manual OPT is the common case), so the step number recorded with each
    submission is looked up rather than assumed to be 1.
    """
    for i, step in enumerate(sequence):
        if step == calc_type:
            return i + 1
    base = calc_type.rstrip("0123456789") or calc_type
    for i, step in enumerate(sequence):
        if (step.rstrip("0123456789") or step) == base:
            return i + 1
    return None


# opt2d12 --calc-type types that no template has a step for: each is a run of its own
OWN_RUN_TYPES = ("ELASTIC", "EOS", "QHA", "CPHF")


def missing_steps_message(decks: List[Path], sequence: List[str], calc_type_of: Callable[[Path], str],
                          what: str = "the template") -> Optional[str]:
    """Why ``decks`` cannot start a workflow of ``sequence``, or None: a deck
    whose calculation type has no step in it would run as step 1 and start
    nothing after it (MACE GUI offers only the templates that hold every
    selected deck's type)."""
    bad = []
    for deck in decks:
        calc_type = calc_type_of(Path(deck))
        if position_in_sequence(calc_type, sequence) is None:
            bad.append((Path(deck).name, calc_type))
    if not bad:
        return None
    from mace.workflow.spec import _a
    msg = (f"{what} ({', '.join(sequence)}) has no step for "
           + ", ".join(f"{name} ({_a(calc_type)} deck)" for name, calc_type in bad))
    if any(calc_type in OWN_RUN_TYPES for _, calc_type in bad):
        msg += ("; ELASTIC, EOS, QHA and CPHF decks are not steps of a workflow template: submit them "
                "without --progress")
    return msg


def describe_plan(plan_file: Path, workflow_id: str, sequence: List[str]) -> None:
    """Tell the user exactly what they just opted into."""
    ui.ok(f"\nWorkflow plan created: {plan_file.name}")
    ui.info(f"  Workflow ID: {workflow_id}")
    ui.info(f"  Sequence:    {' → '.join(sequence)}")
    ui.info("  Completed steps will progress according to this plan.")


def read_launch_plan(plan_file) -> Dict[str, Any]:
    """The plan `mace submit --progress-plan` is given: a deck-start plan
    with its workflow id (`mace workflow --spec SPEC --write-plan`)."""
    import json
    path = Path(plan_file)
    try:
        plan = json.loads(path.read_text())
    except OSError as e:
        raise ValueError(f"cannot read the plan {path}: {e}")
    except ValueError as e:
        raise ValueError(f"{path} is not a workflow plan (not JSON: {e})")
    if not isinstance(plan, dict) or not plan.get("workflow_id") or not plan.get("workflow_sequence"):
        raise ValueError(f"{path} is not a workflow plan with a workflow id "
                         f"(write one with `mace workflow --spec SPEC --write-plan`)")
    if plan.get("input_type") != "d12":
        raise ValueError(f"{path} starts from CIFs; launch it with `mace workflow --execute {path}`")
    return plan


def check_launch_plan(plan: Dict[str, Any], plan_file, base_dir: Path,
                      decks: List[Path]) -> Tuple[Path, str, List[str]]:
    """Refuse what would break the workflow: a plan outside this folder's
    workflow_configs/ (the callbacks would not find it), decks the plan does
    not list, or a plan that was launched already."""
    workflow_id = plan["workflow_id"]
    from mace.workflow.planner import plan_soc_problems
    soc_errors, _soc_warnings = plan_soc_problems(plan)
    if soc_errors:
        raise ValueError("; ".join(soc_errors))
    expected = (Path(base_dir).resolve() / "workflow_configs"
                / f"workflow_plan_{workflow_id[len('workflow_'):]}.json")
    if Path(plan_file).resolve() != expected:
        raise ValueError(f"the plan of {workflow_id} must be {expected} (the job callbacks look "
                         f"for it there); write it in this folder with --work-dir")
    listed = {str(Path(f).resolve()) for f in (plan.get("input_files") or {}).get("d12") or []}
    extra = [Path(d).name for d in decks if str(Path(d).resolve()) not in listed]
    if extra:
        raise ValueError(f"the plan does not list {', '.join(extra)}; submit the decks it was "
                         f"written for")
    db = Path(base_dir).resolve() / f".mace_context_{workflow_id}" / "materials.db"
    if db.is_file():
        import sqlite3
        try:
            with sqlite3.connect(f"file:{db}?mode=ro", uri=True) as conn:
                n = conn.execute("SELECT COUNT(*) FROM calculations").fetchone()[0]
        except sqlite3.Error:
            n = 0
        if n:
            raise ValueError(f"{workflow_id} was launched already ({n} calculation(s) recorded); "
                             f"write a new plan to start again")
    return expected, workflow_id, list(plan["workflow_sequence"])


def own_step_scripts(plan: Dict[str, Any], base_dir: Path) -> Dict[str, Path]:
    """The job-script templates the first submission of ``plan`` must use:
    the workflow's own copy (``.mace_context_<id>/workflow_scripts``), by the
    queue manager's key (``submitcrystal23_opt`` for
    ``submitcrystal23_opt_1.sh``), earliest step first. The folder's
    ``workflow_scripts/`` holds the templates of the plan written last, which
    is another workflow's when two plans were written before either was
    launched."""
    from mace.workflow.context import workflow_scripts_dir
    own = workflow_scripts_dir(base_dir, plan.get("workflow_id") or "")
    steps = plan.get("step_configurations") or {}
    out: Dict[str, Path] = {}
    for i, calc_type in enumerate(plan.get("workflow_sequence") or []):
        scripts = (((steps.get(f"{calc_type}_{i + 1}") or {}).get("slurm_config") or {})
                   .get("scripts") or {})
        for script in scripts.values():
            name = script.get("step_specific_name") if isinstance(script, dict) else None
            if name and name.endswith(".sh") and (own / name).is_file():
                out.setdefault(name[:-3].rsplit("_", 1)[0], own / name)
    return out


# ------------------------------------------------------------------ the first step
# A workflow never writes in the decks' folder: each deck runs in its own step
# folder, workflow_outputs/<id>/step_NNN_<TYPE>/<material>/, as every later step
# does. The files a deck's job script reads beside it ($DIR/$JOB.<ext>,
# mace/submission/submitcrystal23.sh) go with it: a staged density matrix
# (.f20), an EXTERNAL geometry (.ext, or the file the deck's own job script
# copies to fort.34, staged as .ext), and its own .f9 when the deck restarts
# from it (GUESSP, GUESSPSO) or is a properties deck (.d3: Pproperties reads
# the SCF run's wavefunction as $JOB.f9, mace/submission/submit_prop.sh).
_COMPANIONS = (".f20", ".ext")
_GUESSP = re.compile(r"^[ \t]*GUESSP\w*[ \t]*$", re.I | re.M)


# A deck changed after its output was written is run again: that output is
# of the deck as it was. The slack covers a folder copied without its file
# times (cp -r, unzip), where a deck can land a moment after its output.
_EDITED_SLACK_S = 120


def edited_after_output(deck: Path) -> bool:
    """True when ``deck`` was changed after its own ``.out`` was written."""
    try:
        return (Path(deck).stat().st_mtime
                > Path(deck).with_suffix(".out").stat().st_mtime + _EDITED_SLACK_S)
    except OSError:
        return False


def finished_output(deck: Path, calc_type: str) -> Optional[Path]:
    """``deck``'s own output when it is a finished run of ``calc_type`` (the
    completion checker's verdict, which the job callback reads too), else
    None: a failed, stopped or unfinished run is run again, and so is a deck
    changed after its output was written. A symlinked ``.out`` is not the
    deck's own output (MACE GUI never follows one out of its folder, and
    the launch and its preview count the same outputs)."""
    out = Path(deck).with_suffix(".out")
    if out.is_symlink() or not out.is_file() or edited_after_output(deck):
        return None
    from mace.completion_checker import CALC_TYPE_TO_BUCKET, categorize_output_file
    want = CALC_TYPE_TO_BUCKET.get(calc_type.rstrip("0123456789") or calc_type)
    try:
        return out if want and categorize_output_file(out)[0] == want else None
    except Exception:
        return None


def step_folder(base_dir: Path, workflow_id: str, step: int, calc_type: str,
                material_id: str) -> Path:
    """Where a step of ``material_id`` runs (the engine's layout)."""
    return (Path(base_dir).resolve() / "workflow_outputs" / workflow_id
            / f"step_{step:03d}_{calc_type}" / material_id)


def stage_deck(deck: Path, folder: Path, stem: str) -> Path:
    """A copy of ``deck`` as ``folder/<stem><suffix>``, with the files its
    job script reads beside it, renamed alike. The deck and its files are
    only read."""
    import shutil
    deck = Path(deck)
    folder.mkdir(parents=True, exist_ok=True)
    staged = folder / f"{stem}{deck.suffix}"
    shutil.copy2(deck, staged)
    exts = list(_COMPANIONS)
    if deck.suffix.lower() == ".d3" or _GUESSP.search(deck.read_text(errors="replace")):
        exts.append(".f9")
    for ext in exts:
        src = deck.with_suffix(ext)
        if src.is_file():
            shutil.copy2(src, staged.with_suffix(ext))
    from mace.submission.external_geometry import deck_keyword, fort34_source
    if deck_keyword(deck):
        # what the deck's job would stage as fort.34: the step's job script
        # (MACE's) stages <stem>.ext
        src = fort34_source(deck)
        if src is not None:
            shutil.copy2(src, staged.with_suffix(".ext"))
    return staged


def _warn_restart_starts_over(deck: Path) -> None:
    """An OPTGEOM RESTART reads OPTINFO.DAT from the scratch directory of the
    deck's earlier run, which the job script finds through the deck's
    folder (.<JOB>.scratch, and the directory's .mace_submit_dir must name
    that folder): run from its step folder, the deck gets a scratch
    directory of its own, and the job drops RESTART and starts over."""
    if Path(deck).suffix.lower() != ".d12":
        return
    from mace.recovery.opt_restart import has_optgeom_restart
    try:
        restart = has_optgeom_restart(Path(deck).read_text(errors="replace"))
    except OSError:
        return
    if restart:
        ui.warn(f"{Path(deck).name} continues an optimization (OPTGEOM RESTART), but its step folder "
                f"runs it in a new scratch directory without the OPTINFO.DAT of its earlier run: the "
                f"job drops RESTART and starts the optimization over from the deck's geometry. To "
                f"continue it, run it where it is (mace submit {Path(deck).name}, or mace recover) "
                f"and start the workflow from its finished output.")


def material_names(decks: List[Path]) -> Dict[str, Path]:
    """{material_id: deck} of the decks a workflow starts from. Raises
    ValueError when two decks give the same material name (they would share
    a folder and a name in every later step)."""
    from mace.database.materials import create_material_id_from_file
    seen: Dict[str, Path] = {}
    for deck in decks:
        deck = Path(deck).resolve()
        mid = create_material_id_from_file(str(deck))
        if mid in seen:
            raise ValueError(f"{seen[mid].name} and {deck.name} give the same material name {mid}; "
                             f"rename one (each material runs in its own folder of the workflow)")
        seen[mid] = deck
    return seen


def first_steps(decks: List[Path], base_dir: Path, workflow_id: str, sequence: List[str],
                calc_type_of: Callable[[Path], str], rerun_finished: bool = False):
    """The decks of a launched plan, split into (to run, finished):

    - to run: ``(staged deck, material_id, calc_type, folder)``, each deck
      copied into its step folder (``stage_deck``), where its job script is
      written and submitted;
    - finished: ``(deck, material_id, calc_type, output)``, a deck whose own
      output is a finished run of its type. It is not run again: its output
      is read where it is and starts the next steps. With
      ``rerun_finished`` every deck is run.

    Raises ValueError when two decks give the same material name
    (``material_names``), or when a staged EXTERNAL deck has no geometry
    file (``missing_fort34_message``)."""
    from mace.submission.external_geometry import missing_fort34_message
    run, done = [], []
    for mid, deck in material_names(decks).items():
        calc_type = calc_type_of(deck)
        out = None if rerun_finished else finished_output(deck, calc_type)
        if out is None and not rerun_finished and edited_after_output(deck):
            ui.info(f"{deck.name} changed after {deck.with_suffix('.out').name} was written: "
                    f"it runs again")
        if out is not None:
            done.append((deck, mid, calc_type, out))
            continue
        folder = step_folder(base_dir, workflow_id, position_in_sequence(calc_type, sequence) or 1,
                             calc_type, mid)
        run.append((stage_deck(deck, folder, f"{mid}_{calc_type.lower()}"), mid, calc_type, folder))
        _warn_restart_starts_over(deck)
    missing = [m for m in (missing_fort34_message(staged) for staged, *_ in run) if m]
    if missing:
        raise ValueError("\n".join(missing))
    return run, done


def record_finished(manager, deck: Path, material_id: str, calc_type: str, out: Path,
                    stamp: Optional[Callable[[str, str], None]] = None) -> Optional[str]:
    """A finished deck of the plan as a completed row of the workflow's
    database: its deck, folder and output where they are. The engine then
    starts its next steps from that output (``mace workflow --process``)."""
    if not manager.enable_tracking:
        return None
    if not manager.db.get_material(material_id):
        _mid, formula, metadata = manager.extract_material_info_from_d12(deck)
        manager.db.create_material(material_id=material_id, formula=formula, source_type="d12",
                                   source_file=str(deck), metadata=metadata)
    calc_id = manager.db.create_calculation(material_id=material_id, calc_type=calc_type,
                                            input_file=str(deck), work_dir=str(Path(deck).parent))
    if stamp:
        stamp(calc_id, calc_type)
    manager.db.update_calculation_status(calc_id, "completed", output_file=str(out))
    return calc_id
